<body>
  <main class="wrap">
    <h1>Pomodoro</h1>
    <p class="sub">Work for 25 minutes, then take a 5 minute break.</p>

    <div class="card">
      <div class="tabs" role="tablist" aria-label="Timer phase">
        <button class="tab" role="tab" id="tab-work" aria-selected="true">Work · 25:00</button>
        <button class="tab" role="tab" id="tab-break" aria-selected="false">Break · 5:00</button>
      </div>

      <div class="clock">
        <div class="phase" id="phase">Work</div>
        <div class="time" id="time">25:00</div>
        <div class="hint" id="hint" aria-live="polite">Press Start to begin a work session.</div>
      </div>

      <div class="controls">
        <button class="btn primary" id="startPause">Start</button>
        <button class="btn ghost" id="reset">Reset</button>
        <button class="btn ghost" id="skip">Skip</button>
      </div>

      <div class="dots" id="dots" aria-label="Completed work sessions"></div>

      <div class="stats">
        <h2>Progress</h2>
        <p class="empty" id="empty">No rounds completed yet. Finish a work session to earn your first round.</p>
        <div class="grid" id="grid" hidden>
          <div class="stat"><b id="sRounds">0</b><span>rounds</span></div>
          <div class="stat"><b id="sFocus">0m</b><span>focus time</span></div>
          <div class="stat"><b id="sToday">0</b><span>today</span></div>
        </div>
      </div>
    </div>

    <div class="foot">
      <button id="clear">Reset all stats</button>
    </div>
  </main>

<script>
(function () {
  var KEY = 'pomodoro-v1';
  var WORK = 25 * 60, BREAK = 5 * 60;
  var hasStore = !!(window.alfy && window.alfy.storage);

  var timeEl = document.getElementById('time');
  var phaseEl = document.getElementById('phase');
  var hintEl = document.getElementById('hint');
  var startBtn = document.getElementById('startPause');
  var resetBtn = document.getElementById('reset');
  var skipBtn = document.getElementById('skip');
  var clearBtn = document.getElementById('clear');
  var tabWork = document.getElementById('tab-work');
  var tabBreak = document.getElementById('tab-break');
  var dotsEl = document.getElementById('dots');
  var emptyEl = document.getElementById('empty');
  var gridEl = document.getElementById('grid');
  var sRounds = document.getElementById('sRounds');
  var sFocus = document.getElementById('sFocus');
  var sToday = document.getElementById('sToday');

  var state = { mode:'work', running:false, remaining:WORK, rounds:0, focusSec:0, todayKey:'', today:0 };
  var intervalId = null;

  function pad(n){ return String(n).padStart(2,'0'); }
  function fmt(s){ return pad(Math.floor(s/60)) + ':' + pad(s%60); }
  function todayStr(){ var d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }

  function save(){ if(hasStore){ try { window.alfy.storage.set(KEY, state); } catch(e){} } }

  function tick(){
    state.remaining--;
    if (state.mode === 'work') state.focusSec++;
    if (state.remaining <= 0) complete();
    else render();
  }

  function complete(){
    if (state.mode === 'work') {
      state.rounds++;
      state.todayKey = todayStr();
      state.today++;
      state.mode = 'break';
      state.remaining = BREAK;
      hintEl.textContent = 'Work done! Take a 5 minute break.';
    } else {
      state.mode = 'work';
      state.remaining = WORK;
      hintEl.textContent = 'Break over. Start your next work session.';
    }
    save();
    render();
  }

  function start(){
    state.running = true;
    if (intervalId) clearInterval(intervalId);
    intervalId = setInterval(tick, 1000);
    hintEl.textContent = state.mode === 'work' ? 'Stay focused — you\'ve got this.' : 'Relax and rest your eyes.';
    render();
  }

  function pause(){
    state.running = false;
    if (intervalId) { clearInterval(intervalId); intervalId = null; }
    hintEl.textContent = 'Paused.';
    render();
  }

  function reset(){
    state.running = false;
    if (intervalId) { clearInterval(intervalId); intervalId = null; }
    state.remaining = state.mode === 'work' ? WORK : BREAK;
    hintEl.textContent = 'Timer reset.';
    render();
  }

  function skip(){
    state.running = false;
    if (intervalId) { clearInterval(intervalId); intervalId = null; }
    if (state.mode === 'work') {
      state.mode = 'break'; state.remaining = BREAK;
      hintEl.textContent = 'Skipped work. Take a short break.';
    } else {
      state.mode = 'work'; state.remaining = WORK;
      hintEl.textContent = 'Skipped break. Back to work.';
    }
    render();
  }

  function setMode(m){
    state.mode = m;
    state.running = false;
    if (intervalId) { clearInterval(intervalId); intervalId = null; }
    state.remaining = m === 'work' ? WORK : BREAK;
    hintEl.textContent = m === 'work' ? 'Press Start to begin a work session.' : 'Press Start to begin a break.';
    render();
  }

  function render(){
    timeEl.textContent = fmt(state.remaining);
    timeEl.classList.toggle('running', state.running);
    phaseEl.textContent = state.mode === 'work' ? 'Work' : 'Break';
    startBtn.textContent = state.running ? 'Pause' : 'Start';
    tabWork.setAttribute('aria-selected', state.mode === 'work' ? 'true' : 'false');
    tabBreak.setAttribute('aria-selected', state.mode === 'break' ? 'true' : 'false');

    var dots = '';
    var shown = Math.min(state.rounds, 20);
    for (var i = 0; i < shown; i++) dots += '<span class="dot"></span>';
    for (var j = state.rounds; j < 4; j++) dots += '<span class="dot empty"></span>';
    dotsEl.innerHTML = dots;

    if (state.rounds > 0) {
      emptyEl.hidden = true;
      gridEl.hidden = false;
      sRounds.textContent = state.rounds;
      sFocus.textContent = Math.floor(state.focusSec / 60) + 'm';
      sToday.textContent = state.todayKey === todayStr() ? state.today : 0;
    } else {
      emptyEl.hidden = false;
      gridEl.hidden = true;
    }
  }

  startBtn.addEventListener('click', function(){ state.running ? pause() : start(); });
  resetBtn.addEventListener('click', reset);
  skipBtn.addEventListener('click', skip);
  tabWork.addEventListener('click', function(){ setMode('work'); });
  tabBreak.addEventListener('click', function(){ setMode('break'); });

  var confirmClear = false, clearTimer = null;
  clearBtn.addEventListener('click', function(){
    if (!confirmClear) {
      confirmClear = true;
      clearBtn.textContent = 'Tap again to confirm';
      if (clearTimer) clearTimeout(clearTimer);
      clearTimer = setTimeout(function(){ confirmClear = false; clearBtn.textContent = 'Reset all stats'; }, 4000);
      return;
    }
    confirmClear = false;
    if (clearTimer) clearTimeout(clearTimer);
    clearBtn.textContent = 'Reset all stats';
    state.running = false;
    if (intervalId) { clearInterval(intervalId); intervalId = null; }
    state.mode = 'work'; state.remaining = WORK;
    state.rounds = 0; state.focusSec = 0; state.todayKey = ''; state.today = 0;
    hintEl.textContent = 'Stats cleared. Press Start to begin a work session.';
    save();
    render();
  });

  if (hasStore) {
    window.alfy.storage.get(KEY).then(function(saved){
      if (saved && typeof saved === 'object') {
        state.mode = saved.mode === 'break' ? 'break' : 'work';
        state.rounds = typeof saved.rounds === 'number' ? saved.rounds : 0;
        state.focusSec = typeof saved.focusSec === 'number' ? saved.focusSec : 0;
        state.todayKey = typeof saved.todayKey === 'string' ? saved.todayKey : '';
        state.today = typeof saved.today === 'number' ? saved.today : 0;
        state.remaining = (typeof saved.remaining === 'number' && saved.remaining > 0)
          ? saved.remaining : (state.mode === 'work' ? WORK : BREAK);
      }
      render();
    }).catch(function(){ render(); });
  } else {
    render();
  }
})();
</script>
</body>
